import { createRoot } from 'react-dom/client';
import './index.css';
import * as React from 'react';
import { SampleBase } from './sample-base';
import { AccumulationChartComponent, AccumulationSeriesCollectionDirective, AccumulationSeriesDirective, AccumulationLegend, PieSeries, AccumulationDataLabel, AccumulationTooltip, Inject } from '@syncfusion/ej2-react-charts';
import { Browser } from '@syncfusion/ej2/base';
export let data1 = [
    { x: 'Cuba', y: 103800, r: '106', text: 'CUB' },
    { x: 'Syria', y: 185178, r: '133', text: 'SYR' },
    { x: 'Benin', y: 112760, r: '128', text: 'BEN' },
    { x: 'Portugal', y: 91606, r: '114', text: 'POR' },
    { x: 'Austria', y: 82520, r: '111', text: 'AUS' },
    { x: 'Honduras', y: 111890, r: '97', text: 'HON' },
    { x: 'Azerbaijan', y: 82650, r: '125', text: 'AZE' }
];
export class PieRadius extends SampleBase {
    pie;
    render() {
        return (<div className='control-pane'>
      <div className='control-section'>
          <AccumulationChartComponent id='pie-chart' legendSettings={{ visible: false }} enableSmartLabels={true} title='Global Distribution of Population and Land Area by Country - 2025' subTitle='Source: wikipedia.org' enableBorderOnMouseMove={false} enableAnimation={true} load={this.load.bind(this)} loaded={this.loaded.bind(this)} tooltip={{ enable: true, format: '<b>${point.x}</b><br/>Area in square km: <b>${point.y} </b> <br/> Population density per square km: <b>${point.tooltip}</b>', enableHighlight: true }}>
              <Inject services={[AccumulationLegend, PieSeries, AccumulationDataLabel, AccumulationTooltip]}/>
              <AccumulationSeriesCollectionDirective>
                  <AccumulationSeriesDirective dataSource={data1} xName='x' yName='y' innerRadius='20%' tooltipMappingName='r' borderRadius={3} border={{ color: '#FFFFFF', width: 1 }} dataLabel={{ visible: true, position: Browser.isDevice ? 'Inside' : 'Outside', textWrap: Browser.isDevice ? 'Wrap' : 'Normal', name: Browser.isDevice ? 'text' : 'x', font: { size: Browser.isDevice ? '7px' : '12px', fontWeight: '600' }, connectorStyle: { length: Browser.isDevice ? '10px' : '20px', type: 'Curve' } }} radius='r'/>
              </AccumulationSeriesCollectionDirective>
          </AccumulationChartComponent>
      </div>
  </div>);
    }
    load(args) {
        let selectedTheme = location.hash.split('/')[1];
        selectedTheme = selectedTheme ? selectedTheme : 'Fluent2';
        args.accumulation.theme = (selectedTheme.charAt(0).toUpperCase() + selectedTheme.slice(1)).
            replace(/-dark/i, "Dark").replace(/contrast/i, 'Contrast');
    }
    ;
    loaded(args) {
        let chart = document.getElementById('pie-chart');
        chart.setAttribute('title', '');
    }
    ;
}

const root = createRoot(document.getElementById('sample'));
root.render(<PieRadius />);

